'use strict';

// MODULES //

var defaults = require( './../defaults.js' );
var resolveValue = require( './resolve_value.js' );
var resolveTextValue = require( './resolve_text_value.js' );


// VARIABLES //

var PROPS = [
	'align',
	'anchor',
	'angle',
	'baseline',
	'color',
	'dx',
	'dy',
	'font',
	'fontSize',
	'fontStyle',
	'fontWeight',
	'frame',
	'limit',
	'lineHeight',
	'offset',
	'orient',
	'subtitleColor',
	'subtitleFont',
	'subtitleFontSize',
	'subtitleFontStyle',
	'subtitleFontWeight',
	'subtitleLineHeight',
	'subtitlePadding'
];
var TEXT_PROPS = [
	'text',
	'subtitle'
];


// MAIN //

/**
* Synchronizes a title editor configuration with a provided schema.
*
* @private
* @param {Object} conf - title configuration object
* @param {Object} schema - visualization schema
* @returns {Object} mutated configuration object
*/
function config( conf, schema ) {
	var obj;
	var def;
	var i;

	obj = schema.title;
	if ( !obj ) {
		return conf;
	}
	def = defaults.title;
	for ( i = 0; i < TEXT_PROPS.length; i++ ) {
		resolveTextValue( obj, def, conf, TEXT_PROPS[ i ] );
	}
	for ( i = 0; i < PROPS.length; i++ ) {
		resolveValue( obj, def, conf, PROPS[ i ] );
	}
	return conf;
}


// EXPORTS //

module.exports = config;
